-- Document templates (Autorisation des Parents, Fiche Medicale) exported from dev on 2026-09-10.
-- Apply on PROD after the document-template feature is deployed (template_html column must exist).
-- Matched by document_types.code. Idempotent (re-runnable). Also copy deploy/templates/content/*.jpg
-- into the prod site's uploads/content/ folder (the header images the templates reference).
BEGIN;
UPDATE document_types SET template_html = '<img class="rounded-lg" src="/api/v1/content/images/01a08673-f116-7249-9524-a9f2440d3277.jpg"><h1 style="text-align: center;"><br><span style="font-family: &quot;Times New Roman&quot;; font-size: 16pt;">Autorisation des parents (<span data-field="anneeScoute" data-label="Année scoute" class="gndj-field">Année scoute</span>)</span></h1><p style="text-align: center;"></p><p><span style="font-family: &quot;Times New Roman&quot;; font-size: 12pt;">Au Chef de Groupe &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <span data-split="1" class="gndj-split">⇥</span>À la Cheftaine de Groupe</span></p><p></p><p><span style="font-family: &quot;Times New Roman&quot;; font-size: 12pt;">Nous, soussignés <strong><span data-field="prenomPere" data-label="Prénom du père" class="gndj-field">Prénom du père</span> <span data-field="nomPere" data-label="Nom du père" class="gndj-field">Nom du père</span></strong> et <strong><span data-field="prenomMere" data-label="Prénom de la mère" class="gndj-field">Prénom de la mère</span> <span data-field="nomMere" data-label="Nom de la mère" class="gndj-field">Nom de la mère</span></strong> désirons que notre enfant <strong><span data-field="nomComplet" data-label="Nom complet" class="gndj-field">Nom complet</span></strong> poursuive son parcours scout / guide au sein du Groupe Notre-Dame Jamhour.</span></p><p></p><p><span style="font-family: &quot;Times New Roman&quot;; font-size: 12pt;">Notre enfant étant actuellement à l''unité : <strong><span data-field="unite" data-label="Unité" class="gndj-field">Unité</span></strong></span></p><p></p><p><span style="font-family: &quot;Times New Roman&quot;; font-size: 12pt;">Nous nous engageons à lui permettre de participer à toutes les activités organisées par son unité et par le Groupe Notre-Dame Jamhour durant cette année scoute.</span></p><p></p><p><span style="font-family: &quot;Times New Roman&quot;; font-size: 12pt;">Une absence non justifiée à l''avance remettra en question sa participation au mouvement scout du collège.</span></p><p></p><p><span style="font-family: &quot;Times New Roman&quot;; font-size: 12pt;">Signature du père : <span data-w="170" data-fill="1" class="gndj-fill" style="min-width: 170px;">&nbsp;</span> &nbsp;&nbsp; Signature de la mère : <span data-w="170" data-fill="1" class="gndj-fill" style="min-width: 170px;">&nbsp;</span></span></p><p></p><p><span style="font-family: &quot;Times New Roman&quot;; font-size: 12pt;">Date : <span data-w="160" data-fill="1" class="gndj-fill" style="min-width: 160px;">&nbsp;</span></span></p>' WHERE code = 'AUT';
UPDATE document_types SET template_html = '<img class="rounded-lg" src="/api/v1/content/images/01a087bf-6c28-7a72-a2dd-72fd4418c3ff.jpg"><p></p><h1 style="text-align: center;"><span style="font-size: 16pt;">Certificat médical (<span data-field="anneeScoute" data-label="Année scoute" class="gndj-field">Année scoute</span>)</span></h1><p style="text-align: center;"></p><p><span style="font-size: 12pt;">Membre:<strong><span data-field="nomComplet" data-label="Nom complet" class="gndj-field">Nom complet</span></strong>&nbsp;-&nbsp; Unité <strong><span data-field="unite" data-label="Unité" class="gndj-field">Unité</span></strong> - Date de naissance <strong><span data-field="dateNaissance" data-label="Date de naissance" class="gndj-field">Date de naissance</span></strong></span></p><p><span style="font-size: 12pt;">Prénom du père <strong><span data-field="prenomPere" data-label="Prénom du père" class="gndj-field">Prénom du père</span></strong> - Prénom de la mère <strong><span data-field="prenomMere" data-label="Prénom de la mère" class="gndj-field">Prénom de la mère</span></strong></span></p><p><span style="font-size: 12pt;">Groupe sanguin <strong><span data-field="groupeSanguin" data-label="Groupe sanguin" class="gndj-field">Groupe sanguin</span></strong></span></p><p></p><h3><span style="font-size: 12pt;"><strong>Vaccinations (date du dernier rappel)</strong></span></h3><ul><li><p><span style="font-size: 12pt;">Anti diphtérique, tétanos et polio : </span><span style="font-size: 12pt;"><span data-w="160" data-fill="1" class="gndj-fill" style="min-width: 160px;">&nbsp;</span></span></p></li><li><p><span style="font-size: 12pt;">Anti hépatite A : </span><span style="font-size: 12pt;"><span data-w="160" data-fill="1" class="gndj-fill" style="min-width: 160px;">&nbsp;</span></span></p></li><li><p><span style="font-size: 12pt;">Anti typhoïdique Vi : </span><span style="font-size: 12pt;"><span data-w="160" data-fill="1" class="gndj-fill" style="min-width: 160px;">&nbsp;</span></span></p></li><li><p><span style="font-size: 12pt;">Anti ROR (rougeole, oreillons, rubéole) : </span><span style="font-size: 12pt;"><span data-w="160" data-fill="1" class="gndj-fill" style="min-width: 160px;">&nbsp;</span></span></p></li></ul><p></p><h3><span style="font-size: 12pt;"><strong>Antécédents médicaux et chirurgicaux</strong></span></h3><div data-h="60" data-box="1" class="gndj-box" style="height: 60px;"></div><p></p><h3><span style="font-size: 12pt;"><strong>Maladie chronique ou traitement à long terme actuellement suivi</strong></span></h3><div data-h="60" data-box="1" class="gndj-box" style="height: 60px;"></div><p></p><h3><span style="font-size: 12pt;"><strong>Allergies connues</strong></span></h3><p><span style="font-size: 12pt;">Aliments (lactose, gluten…) : </span><span style="font-size: 12pt;"><span data-w="300" data-fill="1" class="gndj-fill" style="min-width: 300px;">&nbsp;</span></span></p><p><span style="font-size: 12pt;">Médicaments : </span><span style="font-size: 12pt;"><span data-w="320" data-fill="1" class="gndj-fill" style="min-width: 320px;">&nbsp;</span></span></p><p><span style="font-size: 12pt;">Autre : </span><span style="font-size: 12pt;"><span data-w="340" data-fill="1" class="gndj-fill" style="min-width: 340px;">&nbsp;</span></span></p><p><span style="font-size: 12pt;">Si oui, veuillez nous informer :</span></p><p><span style="font-size: 12pt;">— du traitement en cas de crise : </span><span style="font-size: 12pt;"><span data-w="280" data-fill="1" class="gndj-fill" style="min-width: 280px;">&nbsp;</span></span></p><p><span style="font-size: 12pt;">— du régime alimentaire spécifique : </span><span style="font-size: 12pt;"><span data-w="260" data-fill="1" class="gndj-fill" style="min-width: 260px;">&nbsp;</span></span></p><p></p><h3><span style="font-size: 12pt;"><strong>Noms, prénoms et coordonnées</strong></span></h3><p><span style="font-size: 12pt;">— du médecin de famille : </span><span style="font-size: 12pt;"><span data-w="300" data-fill="1" class="gndj-fill" style="min-width: 300px;">&nbsp;</span></span></p><p><span style="font-size: 12pt;">— de la personne à contacter en cas d''urgence : </span><span style="font-size: 12pt;"><span data-w="230" data-fill="1" class="gndj-fill" style="min-width: 230px;">&nbsp;</span></span></p><p></p><p><span style="font-size: 12pt;">Je certifie que les informations fournies dans ce certificat médical sont exactes et j''assume l''entière responsabilité en cas d''information médicale non communiquée.</span></p><p></p><p><span style="font-size: 12pt;">Nom / Prénom : </span><span style="font-size: 12pt;"><span data-w="150" data-fill="1" class="gndj-fill" style="min-width: 150px;">&nbsp;</span></span><span style="font-size: 12pt;"> &nbsp; Date : </span><span style="font-size: 12pt;"><span data-w="90" data-fill="1" class="gndj-fill" style="min-width: 90px;">&nbsp;</span></span><span style="font-size: 12pt;"> &nbsp; Signature : </span><span style="font-size: 12pt;"><span data-w="150" data-fill="1" class="gndj-fill" style="min-width: 150px;">&nbsp;</span></span></p>' WHERE code = 'FM';
COMMIT;
